import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CdGZLcRD.js";var i=JSON.parse(`{"title":"Migrate Async Relationship Usage","description":"","frontmatter":{},"headers":[],"relativePath":"skills/relationships/migrate-async-relationship-usage.md","filePath":"skills/relationships/migrate-async-relationship-usage.md"}`),a={name:`skills/relationships/migrate-async-relationship-usage.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrate-async-relationship-usage" tabindex="-1">Migrate Async Relationship Usage <a class="header-anchor" href="#migrate-async-relationship-usage" aria-label="Permalink to “Migrate Async Relationship Usage”">​</a></h1><p>Use this skill whenever code consumes an <code>async: true</code> <code>belongsTo</code> or <code>hasMany</code> relationship implicitly and needs to move toward requests and the <code>resource</code>/<code>collection</code> kinds: a an <code>#each</code> over <code>record.&lt;name&gt;</code>, reads of <code>record.&lt;name&gt;.content</code>, getters or computed properties that reach through a relationship (often several levels deep), or <code>await record.&lt;name&gt;</code>. The human guide <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage">Migrating Async Relationship Usage</a> explains each phase; this skill is the order of operations and the rules for choosing between them.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Inventory the sites before changing anything. Search templates for <code>#each</code> blocks over a relationship property and for relationship properties rendered directly; search JavaScript for <code>.content</code> on a relationship, <code>await record.&lt;name&gt;</code>, <code>@computed</code> dependent keys that cross a relationship (<code>&#39;post.author.company.name&#39;</code>), and <code>.belongsTo(</code>/<code>.hasMany(</code> reference calls. For each site note how many relationship levels the chain crosses; each level is a separate async boundary that will need an owner.</li><li>Do not change the field&#39;s <code>async</code> option or its kind in this pass. Phase 1 works on the legacy field, whose fetch-on-access still runs; only the handling of the resulting promise changes.</li><li>Phase 1, per site, in this order of preference: <ul><li>a template site becomes an <code>&lt;Await /&gt;</code> from <code>@warp-drive/ember</code> with <code>:pending</code>, <code>:error</code> and <code>:success</code> blocks, as in <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage#in-templates-use-await">In templates, use <code>&lt;Await /&gt;</code></a>; for a nested level, pass the inner relationship to a child component and await it there;</li><li>a getter or computed property becomes one <code>getPromiseState</code> call per level, as in <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage#in-getters-and-computed-properties-use-getpromisestate">In getters and computed properties, use <code>getPromiseState</code></a>, replacing <code>@computed</code> dependent keys with plain getters: feed one level&#39;s <code>value</code> into the next level&#39;s <code>getPromiseState</code>, and return <code>null</code> while any outer level is still pending;</li><li>only when neither is a clean refactor (a synchronous utility, a chain with many consumers), read <code>record.hasMany(&#39;&lt;name&gt;&#39;).value()</code> or <code>record.belongsTo(&#39;&lt;name&gt;&#39;).value()</code> and add an explicit <code>.load()</code> where the screen begins, as in <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage#last-resort-read-the-reference-s-value">Last resort: read the reference&#39;s <code>value()</code></a>. Ask the user before choosing this option; it is the shape Phase 3 removes. Never replace a load with <code>.belongsTo(&#39;&lt;name&gt;&#39;).id()</code> or <code>.hasMany(&#39;&lt;name&gt;&#39;).ids()</code>; that pattern has <a href="/pr-preview/pr-11238/upgrading/v5/relationships#patterns-without-a-migration-path">no migration path</a>.</li></ul></li><li>Phase 2: find the request that loads the screen&#39;s parent record and add the relationship (and the chain below it) to its <code>include</code>, rendering inside a <code>&lt;Request /&gt;</code> so the loading state lives at the request. For a relationship that must stay on demand, request its link with a <code>&lt;Request /&gt;</code> instead of letting access fetch it. Follow <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage#phase-2-load-through-requests">Phase 2: Load Through Requests</a>. A field can change to <code>async: false</code> once every request that loads records of <em>its</em> type includes it (<code>post.comments</code> when every post request includes <code>comments</code>; <code>comment.author</code> when every request that loads comments includes <code>author</code>, including via <code>comments.author</code> on the post request). At that point delete its Phase 1 shims.</li><li>Phase 3: convert the fields with <a href="./migrate-relationship-fields">Migrate belongsTo and hasMany Fields to resource and collection</a>, then replace the remaining shims: for an included relationship, delete the <code>&lt;Await /&gt;</code> (and any child component that only existed to await it) and read <code>.data</code> directly; for an on-demand one, fetch <code>doc.links.related</code> through a <code>&lt;Request /&gt;</code> or <code>getPromiseState(doc.fetch())</code>, per <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage#phase-3-move-the-fields-to-resource-and-collection">Phase 3</a>.</li><li>Verify after each of steps 3, 4 and 5: the app renders every migrated screen with an empty cache and with a warm cache; no <code>.content</code> reads or <code>await record.&lt;name&gt;</code> remain for migrated fields; and, in Phase 3, the JSON:API validator reports nothing for the converted fields.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li>Full guide: <a href="/pr-preview/pr-11238/upgrading/v5/relationship-usage">Migrating Async Relationship Usage</a></li><li>Background: <a href="/pr-preview/pr-11238/guides/the-manual/reactivity/derivation">Async as Reactive State</a></li><li>Related skill: <a href="./../requests/fetch-and-cache-data">Fetch and Cache Data</a></li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};